from taf.gnb.oam.coam.cu.interfaces.cuoam23r2 import CUOAM23R2
from taf.gnb.oam.coam.cu.schemas.internal.trs.get_pmtu_discovery_status import GetPmtuDiscoveryStatus
from taf.gnb.oam.coam.cu.schemas.internal.trs.external_interface import ExternalInterface


class CUOAM23R3(CUOAM23R2):
    def start_pmtu_discovery(self, name, source_ip, destination_ip, dscp, timeout=30, raw=False):
        response = self.trs.start_pmtu_discovery(name=name,
                                                 source_ip=source_ip,
                                                 destination_ip=destination_ip,
                                                 dscp=dscp,
                                                 timeout=timeout)
        return response if raw else str(response)

    def get_pmtu_discovery_status(self, operation_id, timeout=30, raw=False):
        response = self.trs.get_pmtu_discovery_status(operation_id=operation_id, timeout=timeout)
        return response if raw else GetPmtuDiscoveryStatus.from_object_dict(response)

    def get_external_interfaces_of_pmtu_discovery(self, timeout=30, raw=False):
        response = self.trs.get_external_interfaces_of_pmtu_discovery(timeout=timeout)
        return ExternalInterface.from_object_dict(response) if not raw else response
